const cfg      = $('⚙️ Config G54').item.json;
const empRaw   = $('🏢 Obtener Empresa G54').item.json;
const prodRaw  = $('📦 Obtener Productos G54').item.json;

const emp  = empRaw.data  || empRaw  || {};
const prods = prodRaw.data || prodRaw || [];

const empresa_nombre = emp.name         || '';
const industria      = emp.industry     || '';
const descripcion    = emp.description  || '';
const valor          = emp.value_proposition || '';
const ciudad         = emp.base_city    || '';
const web            = emp.website      || '';
const objetivo       = emp.primary_goal || '';
const audiencia      = emp.target_market|| '';
const geografia      = emp.geography    || '';
const email          = (emp.emails||[])[0] || 'risosadmi@gmail.com';

const catalogo = prods.map(p => {
  const kw = (p.keywords||[]).join(', ');
  return `• ${p.name||''}: ${p.description||''}${kw?' ['+kw+']':''}`;
}).join('\n');

const prompt = `Actúa como un estratega senior especializado en crecimiento orgánico basado en SEO, AEO y GEO.

Tu función es diseñar una estrategia de contenido que capture demanda, responda preguntas y sea reutilizable por IA.

NEGOCIO: ${empresa_nombre}
INDUSTRIA: ${industria}
DESCRIPCIÓN: ${descripcion}
PROPUESTA DE VALOR: ${valor}
CIUDAD BASE: ${ciudad} | WEB: ${web}
COBERTURA: ${geografia}
OBJETIVO PRINCIPAL: ${objetivo}
MERCADO OBJETIVO: ${audiencia}

PRODUCTOS / SERVICIOS:
${catalogo}

Entrega ÚNICAMENTE un JSON válido con esta estructura exacta (sin markdown, sin texto extra):
{
  "resumen_estrategico": "2-3 párrafos concisos",
  "objetivo": "leads|tráfico|posicionamiento|ventas",
  "audiencia": "descripción del público objetivo",
  "tono": "tono de comunicación recomendado",
  "cta": "URL de conversión principal",
  "pilares": "pilar1, pilar2, pilar3",
  "keyword_strategy": {
    "principales": ["kw principal 1","kw principal 2"],
    "secundarias": ["kw sec 1","kw sec 2","kw sec 3"],
    "long_tail": ["frase larga 1","frase larga 2","frase larga 3"]
  },
  "mapa_preguntas_aeo": ["¿pregunta real 1?","¿pregunta real 2?","¿pregunta real 3?"],
  "clusters": [
    {"nombre":"Cluster 1","keywords":["kw"],"tipo":"TOFU"},
    {"nombre":"Cluster 2","keywords":["kw"],"tipo":"MOFU"},
    {"nombre":"Cluster 3","keywords":["kw"],"tipo":"BOFU"}
  ],
  "embudo": {
    "tofu": ["tema educativo 1","tema educativo 2"],
    "mofu": ["comparativa 1","autoridad 1"],
    "bofu": ["testimonio 1","oferta 1"]
  },
  "canales": ["canal1","canal2"],
  "plan_semanal": {"tofu":3,"mofu":2,"bofu":1},
  "kpis": {
    "seo": ["alcance","impresiones","tráfico"],
    "aeo": ["respuestas guardadas","engagement útil"],
    "geo": ["citas en IA","visibilidad IA"],
    "negocio": ["leads","conversiones","costo por lead"]
  }
}

No generes contenido de redes. Piensa como arquitecto de visibilidad orgánica. Sé específico y accionable para ${empresa_nombre} en ${ciudad}.`;

return [{ json: { empresa_nombre, industria, descripcion, valor, ciudad, web, objetivo, audiencia, geografia, email, catalogo, prompt, company_id: cfg.G54_COMPANY_ID } }];

parameters.jsonBody:
={{ JSON.stringify({
  model: 'llama-3.3-70b-versatile',
  messages: [
    { role: 'system', content: 'Eres un estratega senior de marketing digital especializado en SEO, AEO y GEO. Responde ÚNICAMENTE con JSON válido, sin markdown ni texto adicional.' },
    { role: 'user',   content: $('🔧 Preparar Contexto').item.json.prompt }
  ],
  temperature: 0.7,
  max_tokens: 4096
}) }}

parameters.jsCode:
const raw = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text
  || $input.item.json.choices?.[0]?.message?.content || '{}';

let est;
try { est = JSON.parse(raw); }
catch(e) {
  const m = raw.match(/\{[\s\S]*\}/);
  est = m ? JSON.parse(m[0]) : {};
}

const ctx = $('🔧 Preparar Contexto').item.json;

return [{ json: {
  company_id:        Number(ctx.company_id) || 1,
  resumen_estrategico: est.resumen_estrategico || '',
  objetivo:          est.objetivo  || ctx.objetivo || '',
  audiencia:         est.audiencia || ctx.audiencia|| '',
  tono:              est.tono      || 'profesional y directo',
  cta:               est.cta       || ctx.web + '/contact' || '',
  pilares:           est.pilares   || '',
  keyword_strategy:  est.keyword_strategy  || {},
  mapa_preguntas_aeo:est.mapa_preguntas_aeo|| [],
  clusters:          est.clusters  || [],
  embudo:            est.embudo    || {},
  canales:           est.canales   || [],
  plan_semanal:      est.plan_semanal || { tofu:3, mofu:2, bofu:1 },
  kpis:              est.kpis      || {},
  empresa_nombre:    ctx.empresa_nombre,
  email:             ctx.email
} }];

parameters.message:
={{ (() => {
  const e = $('🔍 Parsear Estrategia').item.json;
  return '<h2>🧠 Estrategia G54 lista para ' + e.empresa_nombre + '</h2>'
    + '<h3>Resumen estratégico</h3><p>' + e.resumen_estrategico + '</p>'
    + '<h3>Keywords principales</h3><p>' + (e.keyword_strategy?.principales||[]).join(', ') + '</p>'
    + '<h3>Canales</h3><p>' + (e.canales||[]).join(', ') + '</p>'
    + '<h3>Plan semanal</h3><p>TOFU: ' + (e.plan_semanal?.tofu||3) + ' | MOFU: ' + (e.plan_semanal?.mofu||2) + ' | BOFU: ' + (e.plan_semanal?.bofu||1) + '</p>'
    + '<p><em>Estrategia guardada en G54. El Content AI la usará en la próxima ejecución.</em></p>';
})() }}
